exports.code = async (inputs) => {
  const incidents = inputs.data || [];
  const total = incidents.length;
  const autoFixed = incidents.filter(i => i.decision === 'auto_remediate').length;
  const escalated = incidents.filter(i => i.decision === 'escalate_to_human').length;
  const successRate = total > 0 ? ((autoFixed / total) * 100).toFixed(1) : '100.0';
  return {
    total_incidents: total,
    auto_remediated: autoFixed,
    escalated: escalated,
    success_rate_percent: successRate
  };
};
